-- What kind of data each declared file holds: what has to be redone when something changes (the project lead's
-- request, 31 October 2026). A first classification by file and by rule (the basis column says which), to be
-- reviewed; a file with several kinds takes the one that decides when it must be rebuilt.
--   base        the base year's data (CAPREG and COCO from statistics): redone with a new base year
--   reference   CAPRI's 2030 reference (levels, prices, coefficients at 2030): redone with a new projection
--   parameter   behavioural and technical parameters (elasticities, cost curves, emission and loss factors, policy
--               rules and targets): changed only by re-estimation or a policy decision
--   calibrated  terms CAPRI computes from the others (PMP terms, curvature matrices, fertiliser priors, need
--               multipliers, land-market terms): recalibrated whenever the base or the baseline changes
--   structure   codes, sets, correspondences
--   validation  results kept for comparison, read by no model code

CREATE TABLE data_kind (
    file VARCHAR PRIMARY KEY,
    kind VARCHAR NOT NULL CHECK (kind IN ('base', 'reference', 'parameter', 'calibrated', 'structure', 'validation')),
    basis VARCHAR NOT NULL
);
COMMENT ON TABLE data_kind IS 'the kind of data of every declared file (base, reference, parameter, calibrated, structure, validation) and the basis of the classification';

